```c
#include <lpc214x.h> // Include LPC2148 header

// Delay function for motor control
void delay(int time) {
    for (int i = 0; i < time; i++);
}

// Function to move X-axis
void move_x(int direction, int steps) {
    if (direction == 1) {
        IO0SET = (1 << 0); // Set X direction to forward
    } else {
        IO0CLR = (1 << 0); // Set X direction to backward
    }
    for (int i = 0; i < steps; i++) {
        IO0SET = (1 << 1); // Step high
        delay(1000);
        IO0CLR = (1 << 1); // Step low
        delay(1000);
    }
}

// Function to move Y-axis
void move_y(int direction, int steps) {
    if (direction == 1) {
        IO0SET = (1 << 2); // Set Y direction to forward
    } else {
        IO0CLR = (1 << 2); // Set Y direction to backward
    }
    for (int i = 0; i < steps; i++) {
        IO0SET = (1 << 3); // Step high
        delay(1000);
        IO0CLR = (1 << 3); // Step low
        delay(1000);
    }
}

// Function to draw a square
void draw_square() {
    move_x(1, 100); // Move X forward
    move_y(1, 100); // Move Y forward
    move_x(0, 100); // Move X backward
    move_y(0, 100); // Move Y backward
}

// Function to draw the letter "A"
void draw_letter_A() {
    // Move to top of "A"
    move_x(1, 50); 
    move_y(1, 100);
    // Move to right diagonal
    move_x(1, 50); 
    move_y(0, 50);
    // Move back to center
    move_x(0, 50); 
    move_y(1, 50);
    // Move to left diagonal
    move_x(0, 50); 
    move_y(0, 50);
    // Move to base
    move_x(1, 50); 
    move_y(1, 50);
    // Move back to start
    move_x(0, 100);
}

int main() {
    // Configure P0.0-P0.3 as output (X/Y direction/step)
    IO0DIR |= (1 << 0) | (1 << 1) | (1 << 2) | (1 << 3);

    while (1) {
        draw_square();      // Draw a square
        draw_letter_A();    // Draw the letter "A"

        // Delay between simulations
        for (volatile int i = 0; i < 100000; i++);
    }
}
```

