Here is a JavaScript function that performs the required operations:

```javascript
function checkDistinctAndCalculateProductSum(array) {
    let isDistinct = array.length === new Set(array).size;
    let product = 1;
    let sum = 0;

    // Collect unique elements
    let uniqueElements = [];
    for (let num of array) {
        if (!uniqueElements.includes(num)) {
            uniqueElements.push(num);
        }
    }

    // Calculate product of unique elements
    for (let num of uniqueElements) {
        product *= num;
    }

    // Calculate sum of all elements
    for (let num of array) {
        sum += num;
    }

    return { isDistinct, product, sum };
}
```

