console.log(checkDistinctAndCalculateProductSum([1, 2, 3, 2, 5]));  // Output: { isDistinct: false, product: 30, sum: 13 }
console.log(checkDistinctAndCalculateProductSum([1, 2, 3, 4, 5]));  // Output: { isDistinct: true, product: 120, sum: 15 }
console.log(checkDistinctAndCalculateProductSum([]));                // Output: { isDistinct: true, product: 1, sum: 0 }
```

