### **Implementation of Stack2**

```java
import java.util.Iterator;
import java.util.NoSuchElementException;

import components.queue.Queue2;
import components.stack.Stack;

public class Stack2<T> extends StackSecondary<T> {
    /* * Private members -------------------------------------------------------- */
    /** * Node class for singly linked list nodes. */
    private final class Node {
        /** * Data in node. */
        private T data;
        /** * Next node in singly linked list, or null. */
        private Node next;

        Node() {
            this.data = null;
            this.next = null;
        }

        Node(T data) {
            this.data = data;
            this.next = null;
        }
    }

    /** * Top node of singly linked list. */
    private Node top;

    /** * Number of nodes in singly linked list, i.e., length = |this|. */
    private int length;

    /** * Creator of initial representation. */
    private void createNewRep() {
        // Initialize the top node with the first element
        Node newNode = new Node();
        newNode.data = T.NULL;
        this.top = newNode;
        this.length = 0;
    }

    /* * Constructors ----------------------------------------------------------- */
    public Stack2() {
        this.createNewRep();
    }

    /* * Standard methods removed to reduce clutter... */
    /* * Kernel methods --------------------------------------------------------- */
    @Override
    public final void push(T x) {
        // Create a new node with x and link it to the top
        Node newNode = new Node(x);
        newNode.next = top;
        top = newNode;
        this.length++;
    }

    @Override
    public final T pop() {
        // Remove the top node and return its data
        if (this.length() == 0) {
            throw new NoSuchElementException();
        }
        T result = this.top.data;
        this.top = this.top.next;
        this.length--;
        return result;
    }

    @Override
    public final int length() {
        return this.length;
    }
}
