import json
from pathlib import Path
from typing import Dict, List, Tuple, Optional

class CodeInjector:
    def __init__(self, config_path: str = "code_injector_config.json"):
        self.config_path = config_path
        self.config = self._load_config()
        self.backups_dir = "code_injector_backups"
        self._create_backups_dir()

    def _create_backups_dir(self):
        """Create backup directory if it doesn't exist"""
        Path(self.backups_dir).mkdir(exist_ok=True)

    def _load_config(self) -> Dict:
        """Load configuration file with file markers"""
        if not os.path.exists(self.config_path):
            return {}

        with open(self.config_path, 'r') as f:
            return json.load(f)

    def _save_config(self, config: Dict):
        """Save updated configuration"""
        with open(self.config_path, 'w') as f:
            json.dump(config, f, indent=2)

    def _backup_file(self, file_path: str):
        """Create a backup of the original file"""
        backup_path = os.path.join(self.backups_dir, os.path.basename(file_path))
        with open(file_path, 'r') as src, open(backup_path, 'w') as dst:
            dst.write(src.read())

    def _find_code_blocks(self, response_text: str) -> List[Tuple[str, str, str]]:
        """Extract code blocks from the response with language and content"""
        pattern = r'```(\w+)\n(.*?)```'
        return [(match.group(1), match.group(2)) for match in re.finditer(pattern, response_text, re.DOTALL)]

    def _apply_code_block(self, file_path: str, code_block: str):
        """Apply code block to the specified file using markers"""
        if not os.path.exists(file_path):
            raise FileNotFoundError(f"File not found: {file_path}")

        self._backup_file(file_path)

        with open(file_path, 'r') as f:
            content = f.read()

        # Find markers in the file
        marker_pattern = r'<!--\s*INSERT_START\s*-->(.*?)<!--\s*INSERT_END\s*-->'
        match = re.search(marker_pattern, content, re.DOTALL)

        if not match:
            raise ValueError(f"Markers not found in {file_path}")

        # Replace content between markers
        new_content = re.sub(
            marker_pattern,
            f'<!-- INSERT_START -->\n{code_block}\n<!-- INSERT_END -->',
            content,
            count=1,
            flags=re.DOTALL
        )

        with open(file_path, 'w') as f:
            f.write(new_content)

    def process_response(self, response_text: str):
