#include <mpi.h>
#include <stdlib.h>
#include <stdio.h>
#include <omp.h>
#define Type double

#if Type == double
#define MPI_TYPE MPI_DOUBLE  // 根据Type类型选择对应的MPI数据类型
#else
#define MPI_TYPE MPI_FLOAT
#endif

// 函数声明
inline Type **Allocate2D(int M, int N);  // 动态分配二维数组
inline void Free(Type **ptr);            // 释放二维数组内存
inline void Swap(Type ***A, Type ***B);  // 交换两个二维数组的指针

int main()
{
    MPI_Init(NULL, NULL);  // 初始化MPI环境
    int rank, numproc;
    FILE *fp;
    FILE *fp_out;
    MPI_Comm_size(MPI_COMM_WORLD, &numproc);  // 获取总进程数
    MPI_Comm_rank(MPI_COMM_WORLD, &rank);     // 获取当前进程的rank

    // rank 0进程创建输入文件
    if (rank == 0)
    {
        fp = fopen("./input_m.txt", "w");
        if (!fp)
        {
            printf("Fail to create file\n");
            exit(0);
        }
    }

    const int N = 1000;  // 矩阵维度

    // 计算当前进程负责的行数范围
    int row_start = (rank * N + numproc - 1) / numproc;
    int row_end = ((rank + 1) * N + numproc - 1) / numproc;
    int subsize = row_end - row_start;  // 当前进程负责的行数

    int *count = (int *)malloc(numproc * sizeof(int));  // 存储每个进程的子矩阵行数
    int *disp = (int *)malloc(numproc * sizeof(int));   // 存储每个进程在总矩阵中的偏移量

    // 收集所有进程的子矩阵行数
    MPI_Gather(&subsize, 1, MPI_INT, count, 1, MPI_INT, 0, MPI_COMM_WORLD);

    if (rank == 0)
    {
        // 将行数转换为元素数量
        for (int i = 0; i < numproc; i++)
            count[i] *= N;
        // 计算每个进程在总矩阵中的偏移量
        disp[0] = 0;
        for (int i = 1; i < numproc; i++)
            disp[i] = disp[i - 1] + count[i - 1];
    }

    Type **A_all = Allocate2D(N, N);  // 用于存储完整矩阵的二维数组
    Type **A = Allocate2D(subsize + 2, N);  // 当前进程负责的子矩阵（含两行缓冲）
    Type **A_tmp = Allocate2D(subsize + 2, N);  // 临时数组用于迭代交换

    // 初始化矩阵边界值
    for (int i = 0; i < subsize + 2; i++)
    {
        for (int j = 0; j < N; j++)
        {
            // 左右边界设为8
            if (j == 0 || j == N - 1)
                A[i][j] = A_tmp[i][j] = 8;
            else
                A[i][j] = A_tmp[i][j] = 0;
        }
    }

    // 顶部边界设为8（仅rank 0进程）
    if (rank == 0)
        for (int j = 0; j < N; j++)
            A[1][j] = A_tmp[1][j] = 8;

    // 底部边界设为8（仅最后一个进程）
    if (rank == numproc - 1)
        for (int j = 0; j < N; j++)
            A[subsize][j] = A_tmp[subsize][j] = 8;

    // 收集所有进程的初始数据到A_all
    MPI_Gatherv(A[1], subsize * N, MPI_TYPE, A_all[0], count, disp, MPI_TYPE, 0, MPI_COMM_WORLD);

    if (rank == 0)
    {
        // 将初始矩阵写入输入文件
        fprintf(fp, "Input data:\n");
        for (int i = 0; i < N; i++)
        {
            fprintf(fp, "\t");
            for (int j = 0; j < N; j++)
                fprintf(fp, "%.2lf ", A_all[i][j]);
            fprintf(fp, "\n");
        }
        fclose(fp);  // 关闭输入文件
    }
    MPI_Barrier(MPI_COMM_WORLD);  // 所有进程同步

    // 建立上下进程关系
    int up = rank - 1;
    int down = rank + 1;
    if (rank == 0)
        up = MPI_PROC_NULL;  // 如果是第一个进程，没有上一个进程
    if (rank == numproc - 1)
        down = MPI_PROC_NULL;  // 如果是最后一个进程，没有下一个进程

    // 迭代计算
    row_start = 1;
    row_end = subsize + 1;
    if (rank == 0)
        row_start = 2;  // 如果是第一个进程，跳过顶部边界行
    if (rank == numproc - 1)
        row_end = subsize;  // 如果是最后一个进程，跳过底部边界行

    double t_start = omp_get_wtime();  // 记录开始时间
    for (int ite = 0; ite < 100; ite++)
    {
        // 发送当前进程的上边界数据到上一个进程，接收上一个进程的下边界数据
        MPI_Sendrecv(A[1], N, MPI_TYPE, up, 0, A[subsize + 1], N, MPI_TYPE, down, 0, MPI_COMM_WORLD, MPI_STATUS_IGNORE);
        // 发送当前进程的下边界数据到下一个进程，接收下一个进程的上边界数据
        MPI_Sendrecv(A[subsize], N, MPI_TYPE, down, 0, A[0], N, MPI_TYPE, up, 0, MPI_COMM_WORLD, MPI_STATUS_IGNORE);

        Swap(&A, &A_tmp);  // 交换数组指针，准备下一次迭代

        // 更新当前进程负责的区域内的矩阵值
        for (int i = row_start; i < row_end; i++)
