stack = []
min_val = None

while True:
    line = input().strip()
    if line == "exit":
        break
    parts = line.split()
    cmd = parts[0]

    if cmd == "push":
        x = int(parts[1])
        stack.append(x)
        if min_val is None or x < min_val:
            min_val = x
    elif cmd == "pop":
        if not stack:
            print("Stack is empty")
        else:
            stack.pop()
    elif cmd == "peek":
        if not stack:
            print("Stack is empty")
        else:
            print(stack[-1])
    elif cmd == "getmin":
        if not stack:
            print("Stack is empty")
        else:
            print(min_val)
```

