#### 2. **Controller Endpoint**

```csharp
[ApiController]
[Route("[controller]")]
public class ExternalApiController : ControllerBase
{
    private readonly IHttpClientFactory _httpClientFactory;

    public ExternalApiController(IHttpClientFactory httpClientFactory)
    {
        _httpClientFactory = httpClientFactory;
    }

    [HttpPost("calt_external_api")]
    public async Task<IActionResult> CaltExternalApi([FromBody] ExternalApiRequest request)
    {
        if (string.IsNullOrEmpty(request.Url) || string.IsNullOrEmpty(request.Api))
        {
            return BadRequest("Url and Api are mandatory.");
        }

        var fullUrl = $"{request.Url.TrimEnd('/')}/{request.Api.TrimStart('/')}";

        using var client = _httpClientFactory.CreateClient();
        var response = await client.GetAsync(fullUrl);

        if (!response.IsSuccessStatusCode)
        {
            return StatusCode((int)response.StatusCode, "External API call failed.");
        }

        var content = await response.Content.ReadAsStringAsync();
        JObject jsonObject = null;
        JArray jsonArray = null;

        try
        {
            if (content.TrimStart().StartsWith("{"))
            {
                jsonObject = JObject.Parse(content);
            }
            else
            {
                jsonArray = JArray.Parse(content);
            }
        }
        catch (JsonException ex)
        {
            return BadRequest("Invalid JSON response from external API.");
        }

        // Apply filter only if it's the /entries API and filter is provided
        if (!string.IsNullOrEmpty(request.Filter) && request.Api == "/entries")
        {
            if (jsonArray != null)
            {
                var filteredArray = new JArray();
                foreach (var item in jsonArray)
                {
                    var category = item["category"]?.ToString();
                    if (category == request.Filter)
                    {
                        filteredArray.Add(item);
                    }
                }
                jsonArray = filteredArray;
            }
        }

        // Return the result based on the parsed JSON
        if (jsonArray != null)
        {
