├── bin/
│   └── console
├── src/
│   └── Command/
│       └── ImapProcessCommand.php
├── composer.json
```

---

### ✅ **Step 3: Console Command Code**

Create the console command in `src/Command/ImapProcessCommand.php`:

```php
<?php

namespace App\Command;

use Symfony\Component\Console\Command\Command;
use Symfony\Component\Console\Input\InputInterface;
use Symfony\Component\Console\Output\OutputInterface;
use Symfony\Component\Console\Input\InputOption;
use PhpImap\ImapManager;
use PhpImap\ImapConfig;

class ImapProcessCommand extends Command
{
    protected function configure()
    {
        $this->setName('imap:process')
             ->setDescription('Process emails and move matched to folder')
             ->addOption('host', 'h', InputOption::VALUE_REQUIRED, 'IMAP host')
             ->addOption('port', 'p', InputOption::VALUE_REQUIRED, 'IMAP port')
             ->addOption('username', 'u', InputOption::VALUE_REQUIRED, 'Username')
             ->addOption('password', 'w', InputOption::VALUE_REQUIRED, 'Password')
             ->addOption('ssl', null, InputOption::VALUE_NONE, 'Use SSL');
    }

    protected function execute(InputInterface $input, OutputInterface $output)
    {
        $host = $input->getOption('host');
        $port = $input->getOption('port');
        $username = $input->getOption('username');
        $password = $input->getOption('password');
        $ssl = $input->getOption('ssl');

        $sslStr = $ssl ? '/imap/ssl' : '/imap';

        $imapConfig = new ImapConfig($host, $port, $sslStr, $username, $password);
        $imapManager = new ImapManager($imapConfig);

        try {
            $imapManager->connect();
            $output->writeln('Connected to IMAP server.');

            $imapManager->selectMailbox('INBOX');
            $output->writeln('Selected INBOX.');

            $mailUids = $imapManager->getUids();
            $fiscalCode = 'VRNHTG14F12D325G';

            foreach ($mailUids as $mailUid) {
                $mail = $imapManager->getMail($mailUid);
                $subject = $mail->getSubject();

                if (strpos($subject, $fiscalCode) !== false) {
                    $output->writeln("Found matching email with subject: $subject");
                    $imapManager->moveMail($mailUid, 'Matched');
                }
            }

            $imapManager->expunge();
            $output->writeln('Processing complete.');

            return Command::SUCCESS;
        } catch (\Exception $e) {
            $output->writeln('Error: ' . $e->getMessage());
            return Command::FAILURE;
        }
    }
}
```

