	"fmt"
	"sort"
)

// Calculate median, mode, and mean of a slice of integers
func calculateStats(data []int) (float64, int, int) {
	// Calculate mean
	mean := 0.0
	for _, num := range data {
		mean += num
	}
	mean /= len(data)

	// Calculate median
	sorted := sort.IntSlice(data)
	if len(sorted) % 2 == 1 {
		median := sorted[len(sorted)/2]
	} else {
		median = (sorted[len(sorted)/2 - 1] + sorted[len(sorted)/2])/2
	}

	// Calculate mode
	mode := findMode(data)
	return mean, median, mode
}

// Helper function to find the mode
func findMode(data []int) int {
	m := make(map[int]int)
	for _, num := range data {
		m[num]++
	}
	maxCount := 0
	modeValue := 0
	for num, count := range m {
		if count > maxCount {
			maxCount = count
			modeValue = num
		} else if count == maxCount {
			if num < modeValue {
				modeValue = num
			}
		}
	}
	return modeValue
}

func main() {
	// Example dataset
	data := []int{10, 20, 15, 5, 7, 12, 18, 19, 25}

	// Calculate statistics
	mean, median, mode := calculateStats(data)
	fmt.Printf("Mean: %.2f\n", mean)
	fmt.Printf("Median: %d\n", median)
	fmt.Printf("Mode: %d\n", mode)
}
```

