```python
text = ''

while True:
    line = input().strip()
    if line == 'quit':
        break
    parts = line.split()
    if not parts:
        continue
    cmd = parts[0]
    try:
        if cmd == 'insert':
            if len(parts) < 3:
                print("Error: insert requires position and text")
                continue
            try:
                pos = int(parts[1])
            except ValueError:
                print("Error: position must be integer")
                continue
            txt = ' '.join(parts[2:])
            text = text[:pos] + txt + text[pos:]
        elif cmd == 'delete':
            if len(parts) < 3:
                print("Error: delete requires start and end")
                continue
            try:
                start = int(parts[1])
                end = int(parts[2])
            except ValueError:
                print("Error: start and end must be integers")
                continue
            if start < 0 or end < start:
                print("Error: invalid start or end")
            else:
                text = text[:start] + text[end:]
        elif cmd == 'search':
            if len(parts) < 2:
                print("Error: search requires substring")
                continue
            substring = parts[1]
            idx = text.find(substring)
            print(idx)
        elif cmd == 'replace':
            if len(parts) < 3:
                print("Error: replace requires old and new")
                continue
            old = parts[1]
            new = parts[2]
            text = text.replace(old, new)
        elif cmd == 'print':
            print(text)
        else:
            print(f"Error: unknown command {cmd}")
    except Exception as e:
        print(f"Error: {e}")
